const invoices = $input.all();

const errorCounts = {};
const validationResults = { FATAL: 0, PASS: 0, REVIEW: 0, WARNING: 0 };
const supplierStats = {};
const timeSeriesData = {};
const fatalErrorDetails = [];
let totalFatalErrors = 0;
let totalReviewErrors = 0;
let totalWarnings = 0;
let lowConfidenceCount = 0;
let newSupplierCount = 0;
let ibanMismatchCount = 0;

for (const item of invoices) {
  const data = item.json;

  if (data.validatieResultaat) {
    validationResults[data.validatieResultaat] = (validationResults[data.validatieResultaat] || 0) + 1;
  }

  const fatalCount = Number(data.aantalFataalFouten) || 0;
  totalFatalErrors += fatalCount;
  totalReviewErrors += Number(data.aantalReviewFouten) || 0;
  totalWarnings += Number(data.aantalWaarschuwingen) || 0;

  if (fatalCount > 0 && data.betrouwbaarheidRedenen) {
    const reasonsStr = String(data.betrouwbaarheidRedenen).trim();
    if (reasonsStr && reasonsStr !== "0") {
      fatalErrorDetails.push({
        factuurnummer: data.factuurnummer || "Onbekend",
        leverancier: data.leveranciernaam || "Onbekend",
        bedrag: data.betaalbaarBedrag || 0,
        redenen: reasonsStr
      });
    }
  }

  if (data.betrouwbaarheidIsLaag) lowConfidenceCount++;
  if (data.nieuweOnbekendeLeverancier) newSupplierCount++;
  if (data.ibanAfwijking) ibanMismatchCount++;

  if (data.leveranciernaam) {
    if (!supplierStats[data.leveranciernaam]) {
      supplierStats[data.leveranciernaam] = { count: 0, totalAmount: 0, errors: 0 };
    }
    supplierStats[data.leveranciernaam].count++;
    supplierStats[data.leveranciernaam].totalAmount += Number(data.betaalbaarBedrag) || 0;
    if (data.validatieResultaat !== "PASS") {
      supplierStats[data.leveranciernaam].errors++;
    }
  }

  if (data.verwerktOp) {
    const dateStr = String(data.verwerktOp);
    const date = dateStr.includes(" ") ? dateStr.split(" ")[0] : dateStr.split("T")[0];
    if (!timeSeriesData[date]) {
      timeSeriesData[date] = { total: 0, passed: 0, failed: 0 };
    }
    timeSeriesData[date].total++;
    if (data.validatieResultaat === "PASS") {
      timeSeriesData[date].passed++;
    } else {
      timeSeriesData[date].failed++;
    }
  }

  if (data.betrouwbaarheidRedenen) {
    const reasonsStr = String(data.betrouwbaarheidRedenen).trim();
    if (reasonsStr && reasonsStr !== "0") {
      const reasons = reasonsStr.split(";").map(r => r.trim()).filter(r => r && r !== "0");
      for (const reason of reasons) {
        errorCounts[reason] = (errorCounts[reason] || 0) + 1;
      }
    }
  }
}

const topErrors = Object.entries(errorCounts)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 10)
  .map(([error, count]) => ({ error, count }));

const topSuppliers = Object.entries(supplierStats)
  .sort((a, b) => b[1].totalAmount - a[1].totalAmount)
  .slice(0, 5)
  .map(([name, stats]) => ({ name, ...stats }));

const timeSeriesArray = Object.entries(timeSeriesData)
  .sort((a, b) => a[0].localeCompare(b[0]))
  .map(([date, stats]) => ({ date, ...stats }));

return [{
  json: {
    validationResults,
    totalFatalErrors,
    totalReviewErrors,
    totalWarnings,
    topErrors,
    topSuppliers,
    timeSeriesData: timeSeriesArray,
    fatalErrorDetails,
    lowConfidenceCount,
    newSupplierCount,
    ibanMismatchCount,
    totalInvoices: invoices.length
  }
}];

const data = $input.first().json;

const validationLabels = Object.keys(data.validationResults).filter(k => data.validationResults[k] > 0);
const validationData = validationLabels.map(k => data.validationResults[k]);

const totalInvoices = data.count_factuurnummer || 1;
const passedInvoices = data.validationResults.PASS || 0;
const failedInvoices = totalInvoices - passedInvoices;
const successRate = ((passedInvoices / totalInvoices) * 100).toFixed(1);

const topErrors = data.topErrors || [];
const topErrorLabels = topErrors.slice(0, 8).map((e, i) => e.error.length > 50 ? e.error.substring(0, 47) + "..." : e.error);
const topErrorData = topErrors.slice(0, 8).map(e => e.count);

const topSuppliers = data.topSuppliers || [];
const supplierLabels = topSuppliers.map(s => s.name.length > 25 ? s.name.substring(0, 22) + "..." : s.name);
const supplierAmounts = topSuppliers.map(s => (s.totalAmount / 1000).toFixed(1));

const timeSeriesData = data.timeSeriesData || [];
const timeLabels = timeSeriesData.map(t => t.date.substring(5));
const timePassedData = timeSeriesData.map(t => t.passed);
const timeFailedData = timeSeriesData.map(t => t.failed);

const validationChartConfig = {
  type: "doughnut",
  data: {
    labels: validationLabels,
    datasets: [{
      data: validationData,
      backgroundColor: ["#f5576c", "#2ed573", "#feca57", "#4facfe"]
    }]
  },
  options: {
    plugins: {
      legend: { position: "bottom", labels: { font: { size: 14 } } },
      title: { display: true, text: "Validatie Status Verdeling", font: { size: 20, weight: "bold" } },
      datalabels: { color: "#fff", font: { size: 16, weight: "bold" }, formatter: (value, ctx) => { return value; } }
    }
  }
};

const errorTypeChartConfig = {
  type: "bar",
  data: {
    labels: ["Fatale Fouten", "Review Fouten", "Waarschuwingen"],
    datasets: [{
      label: "Aantal",
      data: [data.totalFatalErrors, data.totalReviewErrors, data.totalWarnings],
      backgroundColor: ["#f5576c", "#feca57", "#4facfe"]
    }]
  },
  options: {
    plugins: {
      legend: { display: false },
      title: { display: true, text: "Fout Categorieën Overzicht", font: { size: 20, weight: "bold" } },
      datalabels: { anchor: "end", align: "top", font: { size: 14, weight: "bold" } }
    },
    scales: { y: { beginAtZero: true, ticks: { font: { size: 12 } } }, x: { ticks: { font: { size: 12 } } } }
  }
};

const topErrorsChartConfig = {
  type: "bar",
  data: {
    labels: topErrorLabels,
    datasets: [{
      label: "Aantal voorkomens",
      data: topErrorData,
      backgroundColor: "#667eea"
    }]
  },
  options: {
    indexAxis: "y",
    plugins: {
      legend: { display: false },
      title: { display: true, text: "Top Validatiefouten (meest voorkomend)", font: { size: 20, weight: "bold" } },
      datalabels: { anchor: "end", align: "right", font: { size: 13, weight: "bold" }, color: "#333" }
    },
    scales: { x: { beginAtZero: true, ticks: { font: { size: 11 } } }, y: { ticks: { font: { size: 11 } } } }
  }
};

const successRateChartConfig = {
  type: "doughnut",
  data: {
    labels: ["Succesvol (" + successRate + "%)", "Met Fouten"],
    datasets: [{
      data: [passedInvoices, failedInvoices],
      backgroundColor: ["#2ed573", "#ff6b6b"]
    }]
  },
  options: {
    plugins: {
      legend: { position: "bottom", labels: { font: { size: 14 } } },
      title: { display: true, text: "Succes Ratio", font: { size: 20, weight: "bold" } },
      datalabels: { color: "#fff", font: { size: 16, weight: "bold" }, formatter: (value, ctx) => { return value; } }
    }
  }
};

const supplierChartConfig = {
  type: "bar",
  data: {
    labels: supplierLabels,
    datasets: [{
      label: "Bedrag (€1000)",
      data: supplierAmounts,
      backgroundColor: "#764ba2"
    }]
  },
  options: {
    indexAxis: "y",
    plugins: {
      legend: { display: false },
      title: { display: true, text: "Top 5 Leveranciers (op bedrag)", font: { size: 20, weight: "bold" } },
      datalabels: { anchor: "end", align: "right", font: { size: 13, weight: "bold" }, formatter: (value) => "€" + value + "k" }
    },
    scales: { x: { beginAtZero: true, ticks: { font: { size: 11 } } }, y: { ticks: { font: { size: 11 } } } }
  }
};

const trendChartConfig = {
  type: "line",
  data: {
    labels: timeLabels,
    datasets: [
      {
        label: "Succesvol",
        data: timePassedData,
        borderColor: "#2ed573",
        backgroundColor: "rgba(46, 213, 115, 0.1)",
        fill: true,
        tension: 0.4
      },
      {
        label: "Met Fouten",
        data: timeFailedData,
        borderColor: "#ff6b6b",
        backgroundColor: "rgba(255, 107, 107, 0.1)",
        fill: true,
        tension: 0.4
      }
    ]
  },
  options: {
    plugins: {
      legend: { position: "top", labels: { font: { size: 14 } } },
      title: { display: true, text: "Trend over Tijd", font: { size: 20, weight: "bold" } }
    },
    scales: { y: { beginAtZero: true, ticks: { font: { size: 12 } } }, x: { ticks: { font: { size: 11 } } } }
  }
};

const baseUrl = "https://quickchart.io/chart";

return [{
  json: {
    ...data,
    successRate,
    validationChartUrl: `${baseUrl}?c=${encodeURIComponent(JSON.stringify(validationChartConfig))}&width=650&height=450`,
    errorTypeChartUrl: `${baseUrl}?c=${encodeURIComponent(JSON.stringify(errorTypeChartConfig))}&width=650&height=450`,
    topErrorsChartUrl: `${baseUrl}?c=${encodeURIComponent(JSON.stringify(topErrorsChartConfig))}&width=900&height=500`,
    successRateChartUrl: `${baseUrl}?c=${encodeURIComponent(JSON.stringify(successRateChartConfig))}&width=650&height=450`,
    supplierChartUrl: `${baseUrl}?c=${encodeURIComponent(JSON.stringify(supplierChartConfig))}&width=900&height=450`,
    trendChartUrl: `${baseUrl}?c=${encodeURIComponent(JSON.stringify(trendChartConfig))}&width=900&height=400`
  }
}];
